from typing import Any
from langchain_text_splitters import RecursiveCharacterTextSplitter, TextSplitter
from lfx.base.textsplitters.model import LCTextSplitterComponent
from lfx.inputs.inputs import DataInput, IntInput, MessageTextInput, StrInput
from lfx.schema.data import Data
from lfx.schema.message import Message
from lfx.utils.util import unescape_string

class RecursiveCharacterTextSplitterComponent(LCTextSplitterComponent):
    display_name: str = "Recursive Character Text Splitter"
    description: str = "Split text trying to keep all related text together."
    documentation: str = "https://docs.langflow.org/components-processing"
    name = "RecursiveCharacterTextSplitter"
    icon = "LangChain"

    inputs = [
        IntInput(
            name="chunk_size",
            display_name="Chunk Size",
            info="The maximum length of each chunk.",
            value=1000,
        ),
        IntInput(
            name="chunk_overlap",
            display_name="Chunk Overlap",
            info="The amount of overlap between chunks.",
            value=200,
        ),
        DataInput(
            name="data_input",
            display_name="Input",
            info="The texts to split.",
            input_types=["Message", "Document", "Data", "JSON"],
            required=False,
        ),
        MessageTextInput(
            name="separators",
            display_name="Separators",
            info='The characters to split on.',
            is_list=True,
        ),
        StrInput(
            name="course_id",
            display_name="Course ID",
            info="Course ID for multi-tenant isolation.",
            advanced=True,
        ),
        StrInput(
            name="document_id",
            display_name="Document ID",
            info="Document ID.",
            advanced=True,
        ),
        StrInput(
            name="document_name",
            display_name="Document Name",
            info="Document Name.",
            advanced=True,
        ),
    ]

    def get_data_input(self) -> Any:
        return self.data_input

    def transform_data(self) -> list[Data]:
        data_input = self.get_data_input()
        if not data_input:
            return []
        if not isinstance(data_input, list):
            data_input = [data_input]

        meta = {}
        if hasattr(self, "course_id") and self.course_id:
            meta["course_id"] = str(self.course_id)
        if hasattr(self, "document_id") and self.document_id:
            meta["document_id"] = str(self.document_id)
        if hasattr(self, "document_name") and self.document_name:
            meta["document_name"] = str(self.document_name)

        clean_inputs = []
        for item in data_input:
            if not item:
                continue
            if isinstance(item, Message):
                d = item.to_data()
                if meta:
                    d.data.update(meta)
                clean_inputs.append(d)
            elif hasattr(item, "to_data"):
                d = item.to_data()
                if meta:
                    d.data.update(meta)
                clean_inputs.append(d)
            elif isinstance(item, Data):
                if meta:
                    item.data.update(meta)
                clean_inputs.append(item)
            else:
                clean_inputs.append(item)

        if not clean_inputs:
            return []
        self.data_input = clean_inputs
        try:
            docs = super().transform_data()
            if meta and docs:
                for d in docs:
                    if isinstance(d, Data):
                        d.data.update(meta)
            return docs
        except Exception:
            return []

    def build_text_splitter(self) -> TextSplitter:
        if not self.separators:
            separators: list[str] | None = None
        else:
            separators = [unescape_string(x) for x in self.separators]

        return RecursiveCharacterTextSplitter(
            separators=separators,
            chunk_size=self.chunk_size,
            chunk_overlap=self.chunk_overlap,
        )
